import { useCallback, useState } from 'react';

export function useTimePeriodSliderPreview<TEnd>({
  mapIndexToEnd,
  onCommit,
}: {
  mapIndexToEnd: (index: number) => TEnd | null;
  onCommit: (end: TEnd) => void;
}) {
  const [isDragging, setIsDragging] = useState(false);
  const [previewIndex, setPreviewIndex] = useState<number | null>(null);
  const [previewEnd, setPreviewEnd] = useState<TEnd | null>(null);

  const handleDraggingChange = useCallback((dragging: boolean) => {
    setIsDragging(dragging);
    if (!dragging) {
      setPreviewIndex(null);
      setPreviewEnd(null);
    }
  }, []);

  const handleValueChange = useCallback(
    (values: number[]) => {
      const idx = values[0] ?? 0;
      const end = mapIndexToEnd(idx);
      setPreviewIndex(end === null ? null : idx);
      setPreviewEnd(end);
    },
    [mapIndexToEnd],
  );

  const handleValueCommit = useCallback(
    (values: number[]) => {
      const idx = values[0] ?? 0;
      const end = mapIndexToEnd(idx);
      if (end !== null) onCommit(end);
    },
    [mapIndexToEnd, onCommit],
  );

  return {
    isDragging,
    previewIndex,
    previewEnd,
    handleDraggingChange,
    handleValueChange,
    handleValueCommit,
  };
}
